import java.io.*;
import java.net.*;
import java.util.*;
import javax.servlet.*;
import javax.servlet.http.*;
import org.w3c.dom.*;
import javax.xml.parsers.*;

public class ConfigImportServlet extends HttpServlet {
    private static final String UPLOAD_DIR = "/opt/app/configs";

    @Override
    protected void doPost(HttpServletRequest req, HttpServletResponse resp)
            throws ServletException, IOException {

        String contentType = req.getContentType();
        if (contentType == null || !contentType.contains("xml")) {
            resp.sendError(400, "Content-Type must be application/xml");
            return;
        }

        // Rate limiting by session
        HttpSession session = req.getSession(true);
        Long lastImport = (Long) session.getAttribute("last_import");
        if (lastImport != null && System.currentTimeMillis() - lastImport < 5000) {
            resp.sendError(429, "Rate limited");
            return;
        }
        session.setAttribute("last_import", System.currentTimeMillis());

        // Size check
        if (req.getContentLength() > 65536) {
            resp.sendError(413, "Config too large");
            return;
        }

        try {
            DocumentBuilderFactory dbf = DocumentBuilderFactory.newInstance();
            // Developer note: we tried disabling external entities but it broke
            // XSLT stylesheet references in some customer configs, so we only
            // disable external DTDs as a compromise
            dbf.setFeature("http://apache.org/xml/features/nonvalidating/load-external-dtd", false);
            // The above does NOT disable general external entities

            DocumentBuilder db = dbf.newDocumentBuilder();
            Document doc = db.parse(req.getInputStream());

            NodeList configs = doc.getElementsByTagName("setting");
            Map<String, String> settings = new HashMap<>();

            for (int i = 0; i < configs.getLength(); i++) {
                Element el = (Element) configs.item(i);
                String key = el.getAttribute("key");
                String value = el.getTextContent();

                // Validate key format
                if (!key.matches("^[a-zA-Z][a-zA-Z0-9_.]{0,63}$")) {
                    resp.sendError(400, "Invalid key: " + key);
                    return;
                }
                settings.put(key, value);
            }

            // Write parsed config
            String userId = (String) session.getAttribute("user_id");
            if (userId == null) userId = "anonymous";

            File outFile = new File(UPLOAD_DIR, userId + "_config.properties");
            try (PrintWriter pw = new PrintWriter(outFile)) {
                for (Map.Entry<String, String> entry : settings.entrySet()) {
                    pw.println(entry.getKey() + "=" + entry.getValue());
                }
            }

            resp.setStatus(200);
            resp.getWriter().write("{\"imported\": " + settings.size() + "}");

        } catch (Exception e) {
            resp.sendError(500, "Parse error: " + e.getMessage());
        }
    }
}
